<script lang="ts">
  // Справка — статичный текст; значки вместо эмодзи ставит glyphAction.
  import { glyphAction } from '../lib/icons';
  function go(e: MouseEvent) {
    const a = (e.target as HTMLElement).closest('[data-goto]') as HTMLElement | null;
    if (!a) return;
    e.preventDefault();
    document.getElementById(a.dataset.goto!)?.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }
</script>

